IF OBJECT_ID('dbo.CMSPageVersions') IS NULL CREATE TABLE dbo.CMSPageVersions(
 VersionId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PageKey varchar(20) NOT NULL CHECK(PageKey IN('about-us','contact','terms','privacy')),VersionNumber int NOT NULL,ContentJson nvarchar(max) NOT NULL CHECK(ISJSON(ContentJson)=1),Status varchar(20) NOT NULL DEFAULT 'Draft' CHECK(Status IN('Draft','Published','Archived')),
 Revision int NOT NULL DEFAULT 1,EffectiveDate date NULL,RequiresAcceptance bit NOT NULL DEFAULT 0,LegalReviewed bit NOT NULL DEFAULT 0,CreatedBy uniqueidentifier NULL REFERENCES dbo.Users(UserId),UpdatedBy uniqueidentifier NULL REFERENCES dbo.Users(UserId),PublishedBy uniqueidentifier NULL REFERENCES dbo.Users(UserId),PublishedAt datetime2 NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
 CONSTRAINT UQ_CMS_PageVersion UNIQUE(PageKey,VersionNumber),CONSTRAINT CK_CMS_LegalPublished CHECK(Status<>'Published' OR PageKey NOT IN('terms','privacy') OR (LegalReviewed=1 AND PublishedBy IS NOT NULL AND EffectiveDate IS NOT NULL)));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_CMS_Published') CREATE UNIQUE INDEX UX_CMS_Published ON dbo.CMSPageVersions(PageKey) WHERE Status='Published';
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_CMS_Draft') CREATE UNIQUE INDEX UX_CMS_Draft ON dbo.CMSPageVersions(PageKey) WHERE Status='Draft';
IF OBJECT_ID('dbo.LegalDocumentAcceptances') IS NULL CREATE TABLE dbo.LegalDocumentAcceptances(AcceptanceId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(UserId),VersionId uniqueidentifier NOT NULL REFERENCES dbo.CMSPageVersions(VersionId),DocumentType varchar(20) NOT NULL CHECK(DocumentType IN('terms','privacy')),AcceptedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_LegalAcceptance UNIQUE(UserId,VersionId));
IF COL_LENGTH('dbo.ContactMessages','ReferenceNumber') IS NULL ALTER TABLE dbo.ContactMessages ADD ReferenceNumber varchar(40) NULL,FullName nvarchar(200) NULL,RequestKey uniqueidentifier NULL,RequestHash varchar(64) NULL,AssignedTo uniqueidentifier NULL REFERENCES dbo.Users(UserId),ResolvedAt datetime2 NULL;
GO
UPDATE dbo.ContactMessages SET ReferenceNumber=CONCAT('MN-',REPLACE(CONVERT(varchar(36),Id),'-','')),FullName=CONCAT(FirstName,' ',LastName) WHERE ReferenceNumber IS NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Contact_Reference') CREATE UNIQUE INDEX UX_Contact_Reference ON dbo.ContactMessages(ReferenceNumber) WHERE ReferenceNumber IS NOT NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Contact_Request') CREATE UNIQUE INDEX UX_Contact_Request ON dbo.ContactMessages(RequestKey) WHERE RequestKey IS NOT NULL;
IF EXISTS(SELECT 1 FROM sys.check_constraints WHERE name='CK_ContactMessages_Category') ALTER TABLE dbo.ContactMessages DROP CONSTRAINT CK_ContactMessages_Category;
ALTER TABLE dbo.ContactMessages ADD CONSTRAINT CK_ContactMessages_Category CHECK(Category IN('GENERAL','CUSTOMER','BOOKING','QUOTATION','VENDOR','PAYMENT','CANCELLATION','TECHNICAL','PARTNERSHIP','OTHER'));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Contact_CategoryDate') CREATE INDEX IX_Contact_CategoryDate ON dbo.ContactMessages(Category,CreatedAt) INCLUDE(Status,ReferenceNumber,AssignedTo);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Contact_Duplicate') CREATE INDEX IX_Contact_Duplicate ON dbo.ContactMessages(Email,CreatedAt) INCLUDE(RequestHash);
IF OBJECT_ID('dbo.ContactInquiryEvents') IS NULL CREATE TABLE dbo.ContactInquiryEvents(EventId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,InquiryId uniqueidentifier NOT NULL REFERENCES dbo.ContactMessages(Id),EventType varchar(30) NOT NULL CHECK(EventType IN('Note','Reply','Acknowledgement','Status','Assignment')),Body nvarchar(max) NULL,PreviousStatus varchar(30) NULL,NewStatus varchar(30) NULL,CreatedBy uniqueidentifier NULL REFERENCES dbo.Users(UserId),RequestKey uniqueidentifier NULL,DeliveryStatus varchar(20) NULL CHECK(DeliveryStatus IN('Pending','Sending','Sent','Failed','Unknown','Disabled')),LeaseUntil datetime2 NULL,SentAt datetime2 NULL,ErrorMessage nvarchar(500) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_ContactEvents_Inquiry') CREATE INDEX IX_ContactEvents_Inquiry ON dbo.ContactInquiryEvents(InquiryId,CreatedAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_Contact_Ack') CREATE UNIQUE INDEX UX_Contact_Ack ON dbo.ContactInquiryEvents(InquiryId) WHERE EventType='Acknowledgement';
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='UX_ContactEvent_Key') CREATE UNIQUE INDEX UX_ContactEvent_Key ON dbo.ContactInquiryEvents(CreatedBy,RequestKey) WHERE RequestKey IS NOT NULL;
IF OBJECT_ID('dbo.PrivacyRequests') IS NULL CREATE TABLE dbo.PrivacyRequests(RequestId uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(UserId),RequestType varchar(30) NOT NULL CHECK(RequestType IN('Access','Correction','AccountDeletion','DataDeletion','WithdrawConsent','Question')),Description nvarchar(max) NOT NULL,Status varchar(30) NOT NULL DEFAULT 'New' CHECK(Status IN('New','InProgress','WaitingForCustomer','Resolved','Closed')),AdminResponse nvarchar(max) NULL,AssignedTo uniqueidentifier NULL REFERENCES dbo.Users(UserId),RequestKey uniqueidentifier NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ResolvedAt datetime2 NULL,CONSTRAINT UQ_Privacy_Key UNIQUE(UserId,RequestKey));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Privacy_Status') CREATE INDEX IX_Privacy_Status ON dbo.PrivacyRequests(Status,CreatedAt) INCLUDE(UserId);
GO
CREATE OR ALTER TRIGGER dbo.TR_CMS_Immutable ON dbo.CMSPageVersions AFTER UPDATE,DELETE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.VersionId=d.VersionId WHERE d.Status IN('Published','Archived') AND (i.VersionId IS NULL OR i.Status<>'Archived' OR EXISTS(SELECT i.PageKey,i.VersionNumber,i.ContentJson COLLATE Latin1_General_100_BIN2,i.EffectiveDate,i.RequiresAcceptance,i.LegalReviewed,i.PublishedBy,i.PublishedAt EXCEPT SELECT d.PageKey,d.VersionNumber,d.ContentJson COLLATE Latin1_General_100_BIN2,d.EffectiveDate,d.RequiresAcceptance,d.LegalReviewed,d.PublishedBy,d.PublishedAt))) THROW 51000,'Published legal and CMS content is immutable; create a new draft.',1;
END;
